INSERT INTO `categories` VALUES (1,'Car Batteries','car-batteries','Batteries for personal cars — hatchbacks, sedans and SUVs.',NULL,1,1,1,'Car Batteries - Buy Online | Trikuti Battery','Shop Car Batteries online with warranty and old battery exchange in Mumbai.','2026-04-30 07:23:10','2026-08-12 04:34:54'),(2,'Bike Batteries','bike-batteries','Two-wheeler batteries for motorcycles and scooters. Coming soon.',NULL,2,0,0,'Bike Batteries - Buy Online | Trikuti Battery','Shop Bike Batteries online with warranty and old battery exchange in Mumbai.','2026-04-30 07:23:10','2026-08-12 04:59:28'),(3,'Hatchback Batteries','hatchback-batteries','Legacy — merged into Car Batteries.',NULL,5,0,0,'Hatchback Batteries - Buy Online | Trikuti Battery','Shop Hatchback Batteries online with warranty and old battery exchange in Mumbai.','2026-08-12 04:26:48','2026-08-12 04:34:54'),(4,'Sedan Batteries','sedan-batteries','Legacy — merged into Car Batteries.',NULL,6,0,0,'Sedan Batteries - Buy Online | Trikuti Battery','Shop Sedan Batteries online with warranty and old battery exchange in Mumbai.','2026-08-12 04:26:48','2026-08-12 04:34:54'),(5,'SUV Batteries','suv-batteries','Legacy — merged into Car Batteries.',NULL,7,0,0,'SUV Batteries - Buy Online | Trikuti Battery','Shop SUV Batteries online with warranty and old battery exchange in Mumbai.','2026-08-12 04:26:48','2026-08-12 04:34:54'),(6,'MUV & Commercial Batteries','muv-commercial-batteries','Legacy — split into Tempo and Truck.',NULL,8,0,0,'MUV & Commercial Batteries - Buy Online | Trikuti Battery','Shop MUV & Commercial Batteries online with warranty and old battery exchange in Mumbai.','2026-08-12 04:26:48','2026-08-12 04:34:54'),(7,'Tempo Batteries','tempo-batteries','Heavy-duty batteries for tempos, MUVs and small commercial vehicles — Innova Crysta diesel, Tempo Traveller, Bolero Pickup.',NULL,3,1,1,'Tempo Batteries - Buy Online | Trikuti Battery','Shop Tempo Batteries online with warranty and old battery exchange in Mumbai.','2026-08-12 04:34:54','2026-08-12 04:34:54'),(8,'Truck Batteries','truck-batteries','High-capacity batteries for trucks and heavy commercial vehicles. Coming soon.',NULL,4,0,0,'Truck Batteries - Buy Online | Trikuti Battery','Shop Truck Batteries online with warranty and old battery exchange in Mumbai.','2026-08-12 04:34:54','2026-08-12 04:59:28');
