INSERT INTO `testimonials` VALUES (1,'Rahul Sharma','Software Engineer',NULL,'Rabale',5,'Ordered at 11am, battery installed at my doorstep by 3pm. Couldn\'t believe how fast it was. Genuine Exide product, perfect service.',1,1,'2026-04-30 07:23:10','2026-07-31 04:33:22'),(3,'Aman Verma','Business Owner',NULL,'Vashi',4,'Better price than the local Amaron dealer and full warranty card with proper bill. Will buy again.',1,3,'2026-04-30 07:23:10','2026-07-31 04:33:22'),(5,'Vikas Deshpande','Accountant',NULL,'Mulund',5,'Delivery was faster than expected — arrived the next morning as promised. The team called before coming and installation took under 15 minutes.',1,5,'2026-07-31 04:33:22','2026-08-04 01:12:56'),(7,'Rakesh Mehta','Doctor',NULL,'Airoli',5,'Old battery pickup saved me a trip to the scrap dealer. Got ₹700 off instantly. Highly recommended for anyone in Navi Mumbai.',1,2,'2026-07-31 04:35:00','2026-07-31 04:35:00'),(8,'Ravi Reddy','Teacher',NULL,'Thane',5,'Was hesitant about ordering a battery online but the experience was smooth. Delivered next day, technician was professional.',1,4,'2026-07-31 04:35:00','2026-07-31 04:35:00'),(9,'Sagar Patil','HR Manager',NULL,'Bhandup',5,'Great experience — pricing was transparent, invoice was clean, and the warranty card was activated on the spot.',1,6,'2026-07-31 04:35:00','2026-07-31 04:35:00');
